// Reading documents stay in the vault; the browser keeps a recovery draft.
export const readingWords = text => String(text || '').trim().split(/\s+/u).filter(Boolean).length;
export function quotationMarkdown({text, page, context, interpretation, checked}) {
 if(!text.trim() || !page.trim() || !context.trim())throw new Error('Add the exact passage, its page or location, and its context.');
 return `### Passage · ${page.trim().replace(/[\r\n]+/g,' ')}\n\n${text.trim().split('\n').map(line=>'> '+line).join('\n')}\n\n**Page / location:** ${page.trim()}\n\n**Context:** ${context.trim()}\n\n**My interpretation / limits:** ${interpretation.trim()}\n\n**Checked against source by me:** ${checked?'Yes':'Not yet'}\n`;
}
export const readingFeedbackIsCurrent = (review, text) => review.reviewed_text === String(text || '').trim();
const protectedFields=new Set(['Source note (reference copy)','Chapters']);
const clone=value=>JSON.parse(JSON.stringify(value));

export function createReadingUI({api,esc,toast,modal,isCurrent}) {
 let ctx=null,saveTimer=null,pollTimer=null,catalogue=null;
 const $=s=>document.querySelector(s),base=id=>'/reading/'+encodeURIComponent(id),href=id=>'#reading/'+encodeURIComponent(id);
 const active=c=>ctx===c&&isCurrent(c.serial);
 const storage=id=>'awl-reading-draft-'+id;
 function local(id){try{return JSON.parse(localStorage.getItem(storage(id))||'null')}catch{return null}}
 function keep(c){try{localStorage.setItem(storage(c.note.id),JSON.stringify({hash:c.note.hash,fields:c.fields}));return true}catch{return false}}
 function clear(c){try{localStorage.removeItem(storage(c.note.id))}catch{}}
 function message(c,text,error=false){if(active(c)&&$('#reading-save-status')){$('#reading-save-status').textContent=text;$('#reading-save-status').classList.toggle('error',error)}}
 function changed(c){c.dirty=true;c.edit++;const kept=keep(c);message(c,c.error|| (kept?'Draft kept in this browser · saving to Obsidian…':'Saving to Obsidian · browser recovery is unavailable'),!!c.error);clearTimeout(saveTimer);if(!c.error)saveTimer=setTimeout(()=>save(c),1200);updateCount(c)}
 function updateCount(c){if(!active(c))return;$('#reading-word-count').textContent=readingWords(c.fields['My summary'])+' words';if(c.reviews?.length)drawReviews(c)}
 function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 function draftText(c){return '# '+c.note.title+'\n\n'+Object.entries(c.fields).map(([k,v])=>'## '+k+'\n\n'+v).join('\n\n')}
 async function save(c=ctx){
  if(!c)return true;clearTimeout(saveTimer);
  if(c.saving){await c.saving;return c.error?false:c.dirty?save(c):true}
  if(c.error)return false;if(!c.dirty)return true;
  const edit=c.edit,fields=Object.fromEntries(Object.entries(c.fields).filter(([k])=>!protectedFields.has(k)));
  c.saving=(async()=>{try{
   const result=await api(base(c.note.id),{base_hash:c.note.hash,fields},'PUT');c.note=result;
   if(c.edit===edit){c.dirty=false;clear(c)}else keep(c);
   message(c,'Saved to Obsidian · '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}));return true;
  }catch(e){c.error=e.message;keep(c);message(c,e.message,true);showRecovery(c);return false}finally{c.saving=null}})();
  const ok=await c.saving;return ok&&c.dirty?save(c):ok;
 }
 function showRecovery(c){
  if(!active(c))return;const recovery=local(c.note.id),host=$('#reading-recovery');if(!recovery&&!c.error){host.hidden=true;return}
  host.hidden=false;host.innerHTML=`<strong>${c.error?'Your edits are preserved for comparison.':'An unsaved browser draft is available.'}</strong><p>${esc(c.error||'Choose whether to continue these earlier edits.')}</p><div class="actions"><button class="btn secondary" id="reading-recover">${recovery?.hash===c.note.hash&&!c.error?'Resume browser draft':'Compare saved versions'}</button><button class="btn quiet" id="reading-recovery-download">Download my draft</button><button class="btn quiet" id="reading-use-saved">Use current vault version</button></div>`;
  $('#reading-recover').onclick=async()=>{
   if(recovery?.hash===c.note.hash&&!c.error){c.fields=recovery.fields;c.edit++;c.dirty=true;setFields(c);host.hidden=true;await save(c)}else await history(c);
  };
  $('#reading-recovery-download').onclick=()=>download(c.note.title+' - recovery.md',recovery?'# '+c.note.title+'\n\n'+Object.entries(recovery.fields).map(([k,v])=>'## '+k+'\n\n'+v).join('\n\n'):draftText(c));
  $('#reading-use-saved').onclick=async()=>{if(!confirm('Use the current vault version? Download the browser draft first if you want to keep that copy.'))return;c.dirty=false;c.error=null;clear(c);await render(c.note.id,c.serial)};
 }
 function setFields(c){document.querySelectorAll('[data-reading-field]').forEach(el=>{el.value=c.fields[el.dataset.readingField]||''});updateCount(c)}
 async function history(c){
  const [latest,versions]=await Promise.all([api(base(c.note.id)),api(base(c.note.id)+'/history')]);if(!active(c))return;
  const recovery=local(c.note.id),draft=recovery?.fields||c.fields;
  modal('Compare reading versions',`<p>Both versions are kept. Compare the summary and supporting notes before choosing what to save.</p><div class="reading-compare"><section><h3>My browser draft</h3><pre>${esc(draft['My summary']||'(empty summary)')}</pre><details><summary>All fields</summary><pre>${esc(JSON.stringify(draft,null,2))}</pre></details></section><section><h3>Current Obsidian note</h3><pre>${esc(latest.fields['My summary']||'(empty summary)')}</pre><details><summary>All fields</summary><pre>${esc(JSON.stringify(latest.fields,null,2))}</pre></details></section></div><details><summary>Earlier saved versions (${versions.length})</summary>${versions.map(v=>`<details><summary>${esc(new Date(v.created).toLocaleString())} · ${esc(v.origin)}</summary><pre>${esc(Object.entries(v.fields).map(([k,t])=>k+'\n'+t).join('\n\n'))}</pre></details>`).join('')}</details><label class="reading-check"><input type="checkbox" id="reading-compared"> I compared the versions and want my browser draft to become the current note.</label><button class="btn" id="reading-resolve" disabled>Save my compared draft</button><p id="reading-resolve-status" role="status"></p>`);
  $('#reading-compared').onchange=e=>{$('#reading-resolve').disabled=!e.target.checked};
  $('#reading-resolve').onclick=async()=>{const button=$('#reading-resolve');button.disabled=true;try{
   const result=await api(base(c.note.id),{base_hash:latest.hash,fields:Object.fromEntries(Object.entries(draft).filter(([k])=>!protectedFields.has(k))),merge_heads:latest.heads.map(h=>h.id)},'PUT');
   c.note=result;c.fields=clone(result.fields);c.error=null;c.dirty=false;clear(c);$('#modal').close();setFields(c);showRecovery(c);message(c,'Compared draft saved to Obsidian.');
  }catch(e){$('#reading-resolve-status').textContent=e.message;button.disabled=false}};
 }
 function templateOptions(selected='reading'){return catalogue.templates.map(t=>`<option value="${esc(t.id)}" ${selected===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}
 function createForm({book=null,source=null}={}){
  modal(book?'Add a chapter document':'Start a reading document',`<form id="reading-create"><label class="field">${book?'Chapter title':'Title'}<input name="title" value="${esc(source?.title||'')}" maxlength="180" required autofocus></label>${book?'':`<label class="field">Document type<select name="kind"><option value="paper">Paper summary</option><option value="book">Book overview</option><option value="note">Other academic reading</option></select></label>`}<label class="field">Starting template<select name="template">${templateOptions(book?'reading':'literature')}</select></label><details><summary>Author, reference and pages</summary><label class="field">Author<input name="author" value="${esc(source?.author||'')}" maxlength="600"></label><label class="field">Year<input name="year" value="${esc(source?.year||'')}" maxlength="30"></label><label class="field">DOI, citation or source link<textarea name="reference" maxlength="2000" rows="2"></textarea></label><label class="field">${book?'Chapter number / pages':'Pages / location'}<input name="pages" maxlength="100"></label></details><p>${source?'The source note stays intact. Its overview is shown as reference material; your own summary starts empty.':book?'This creates a separate Markdown document linked to the book overview.':'A folder named after this work is created in your Obsidian vault.'}</p><button class="btn" type="submit">${book?'Create chapter':'Create reading document'}</button><p id="reading-create-status" role="status"></p></form>`);
  $('#reading-create').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget),button=event.currentTarget.querySelector('button[type=submit]');button.disabled=true;try{
   const note=await api('/reading',{title:f.get('title'),kind:book?'chapter':f.get('kind'),template:f.get('template'),parent_id:book?.id||null,source_id:source?.id||null,author:f.get('author')||'',year:f.get('year')||'',reference:f.get('reference')||'',pages:f.get('pages')||''});
   $('#modal').close();if(note.notice)toast(note.notice);location.hash=href(note.id);
  }catch(e){$('#reading-create-status').textContent=e.message;button.disabled=false}};
 }
 async function home(serial){
  catalogue=await api('/reading');if(!isCurrent(serial))return;
  if(!catalogue.enabled){$('#main').innerHTML='<h1>Reading & notes</h1><p>Connect your Obsidian vault to keep reading documents available on your computers.</p><a class="btn" href="#papers">Choose my vault</a>';return}
  $('#main').innerHTML=`<div class="reading-home"><header class="reading-hero"><div><span class="eyebrow">READ · UNDERSTAND · WRITE</span><h1>Make the reading your own.</h1><p>Summarise a paper, work through a book chapter, and keep exact quotations beside your own thinking.</p><button class="btn" id="reading-new">New reading document</button></div><aside><span>ONE SOURCE, THREE DISTINCT THINGS</span><ol><li><strong>The author’s words</strong><small>Quotations with context and pages</small></li><li><strong>Your understanding</strong><small>A summary in your own voice</small></li><li><strong>Your judgement</strong><small>Questions, limits and connections</small></li></ol></aside></header>
  <section class="card reading-library"><div class="reading-section-head"><h2>Your reading documents</h2><label class="field">Find a paper or book<input id="reading-find" type="search" placeholder="Title or author"></label></div><div id="reading-documents"></div></section>
  <details class="card reading-source-search"><summary>Start from an existing Obsidian literature card</summary><p>Search the shared literature library. The original card stays in place.</p><label class="field">Title, author, topic or citation key<input id="reading-source-query" type="search" placeholder="e.g. process mining or an author’s name"></label><div id="reading-source-results" aria-live="polite"></div></details>
  <details class="card"><summary>Templates and where your work is saved</summary><p>Current notes, version history and completed tutor feedback live in <strong>${esc(catalogue.folder)}</strong>. Let Obsidian Sync finish before changing devices.</p><ul>${catalogue.templates.map(t=>`<li><strong>${esc(t.title)}</strong> · ${esc(t.source)}</li>`).join('')}</ul><p>You can also read and edit these Markdown notes in Obsidian on iPad. The native iPad Writing Lab does not yet include this reading desk.</p></details>${catalogue.issues.length?`<details class="alert"><summary>Some vault notes need attention</summary><ul>${catalogue.issues.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`:''}</div>`;
  $('#reading-new').onclick=()=>createForm();
  function cards(){const query=$('#reading-find').value.toLowerCase(),docs=catalogue.documents.filter(n=>(n.title+' '+n.author).toLowerCase().includes(query));$('#reading-documents').innerHTML=docs.length?`<div class="reading-card-grid">${docs.map(n=>`<a class="reading-document" href="${href(n.id)}"><span class="tag">${esc(n.kind==='note'?'Academic note':n.kind)}</span><h3>${esc(n.title)}</h3><p>${esc([n.author,n.year].filter(Boolean).join(' · '))}</p><span>${n.has_summary?'Summary drafted':'Ready for your words'}${n.kind==='book'?' · '+catalogue.documents.filter(c=>c.parent_id===n.id).length+' chapters':''}</span></a>`).join('')}</div>`:'<p class="muted">No matching reading documents. Start one above, or choose a source card below.</p>'}
  $('#reading-find').oninput=cards;cards();let searchTimer,searchNumber=0;
  $('#reading-source-query').oninput=()=>{clearTimeout(searchTimer);const q=$('#reading-source-query').value.trim(),number=++searchNumber;searchTimer=setTimeout(async()=>{try{if(!isCurrent(serial))return;if(q.length<2){$('#reading-source-results').textContent='Type at least two characters.';return}const results=await api('/workspace/literature?q='+encodeURIComponent(q)+'&scope=all');if(!isCurrent(serial)||number!==searchNumber)return;$('#reading-source-results').innerHTML=results.entries.length?results.entries.map(s=>`<button class="reading-source-result" data-source="${esc(s.id)}"><strong>${esc(s.title)}</strong><small>${esc([s.author,s.year].filter(Boolean).join(' · '))} · Start my own reading note →</small></button>`).join(''):'<p>No matching sources.</p>';document.querySelectorAll('[data-source]').forEach(button=>button.onclick=()=>createForm({source:results.entries.find(s=>s.id===button.dataset.source)}))}catch(e){if(isCurrent(serial))$('#reading-source-results').textContent=e.message}},350)};
 }
 async function render(id,serial){
  if(!id){await home(serial);return}
  const [note,reviews,cat]=await Promise.all([api(base(id)),api(base(id)+'/reviews'),api('/reading')]);if(!isCurrent(serial))return;catalogue=cat;
  ctx={note,fields:clone(note.fields),reviews,serial,edit:0,dirty:false,error:null,saving:null};const c=ctx;
  const extras=Object.keys(note.fields).filter(k=>!['My summary','Quotations with context','Reading objective',...protectedFields].includes(k));
  $('#main').innerHTML=`<div class="reading-desk"><div class="reading-section-head"><a href="#reading">← Reading & notes</a><div class="actions"><a class="btn quiet" href="${esc(note.uri)}">Open in Obsidian ↗</a><button class="btn quiet" id="reading-history">Saved versions</button><button class="btn quiet" id="reading-plan-task">Send to planner</button><button class="btn secondary" id="reading-save">Save now</button></div></div><header class="reading-title"><span class="eyebrow">${esc(note.kind==='chapter'?'CHAPTER DOCUMENT':note.kind==='book'?'BOOK OVERVIEW':'READING DOCUMENT')}</span><h1>${esc(note.title)}</h1>${note.parent?`<a href="${href(note.parent.id)}">↑ ${esc(note.parent.title)}</a>`:''}<p id="reading-save-status" role="status">Saved in Obsidian · ${esc(note.vault_path)}</p></header>
  <section id="reading-recovery" class="alert" hidden></section>
  ${note.kind==='book'?`<section class="reading-chapters card"><div class="reading-section-head"><h2>Chapter documents</h2><button class="btn secondary" id="reading-add-chapter">Add a chapter</button></div><p>Write the whole-book synthesis here. Each chapter has its own summary, quotations and tutor feedback.</p><ol>${note.children.map(n=>`<li><a href="${href(n.id)}">${esc(n.title)}</a></li>`).join('')}</ol>${!note.children.length?'<p class="muted">Add the first chapter when you are ready.</p>':''}</section>`:''}
  <div class="reading-work-grid"><section class="card reading-summary"><label for="reading-summary"><h2>My summary · my own words</h2></label><p class="muted">Explain what the author argues and the evidence or qualifications that matter. Keep your critique distinct.</p><textarea id="reading-summary" data-reading-field="My summary" maxlength="60000" placeholder="After reading, explain the central idea in your own words…">${esc(c.fields['My summary']||'')}</textarea><div class="reading-section-head"><span id="reading-word-count"></span><button class="btn quiet" id="reading-focus">Focus on this summary</button></div>
  <details class="reading-plan"><summary>Reading objective and working notes</summary><label class="field">Reading objective<textarea data-reading-field="Reading objective" rows="3" maxlength="60000">${esc(c.fields['Reading objective']||'')}</textarea></label>${extras.map(k=>`<details><summary>${esc(k)}</summary><label class="field">${esc(k)}<textarea data-reading-field="${esc(k)}" rows="6" maxlength="60000">${esc(c.fields[k]||'')}</textarea></label></details>`).join('')}</details></section>
  <aside class="reading-sources card"><div class="reading-section-head"><h2>The author’s words</h2><button class="btn secondary" id="reading-add-quote">Add quotation</button></div><p>Copy exactly from the source, add its location and context, then write your interpretation separately.</p><label class="field">Quotation notebook<textarea data-reading-field="Quotations with context" rows="12" maxlength="60000" placeholder="> Exact source words\n\nPage / location:\nContext:\nMy interpretation / limits:">${esc(c.fields['Quotations with context']||'')}</textarea></label><p class="tiny">Quoted lines start with &gt;. The tutor receives this notebook when it contains quoted source text; it does not read the full paper.</p>${note.fields['Source note (reference copy)']?`<details><summary>Original literature-card notes · reference only</summary><pre>${esc(note.fields['Source note (reference copy)'])}</pre></details>`:''}</aside></div>
  <section class="card reading-tutor"><div class="reading-section-head"><div><span class="eyebrow">A SECOND READER</span><h2>Tips on my summary</h2></div><a href="#settings">Local tutor settings</a></div><p>Ask a specific question. The tutor comments on your saved summary and any quoted excerpts. You can keep editing while it reads.</p><div class="reading-question-row"><label class="field">Review focus<select id="reading-review-focus"><option value="general">Meaning and organisation</option><option value="clarity">Clarity and academic English</option><option value="faithfulness">Faithfulness to my excerpts</option></select></label><label class="field">My question<textarea id="reading-question" rows="3" maxlength="1500">What is already clear, and what one or two changes would improve this summary without changing my meaning?</textarea></label></div><button class="btn" id="reading-ask">Save summary & ask local tutor</button><p id="reading-tutor-status" role="status"></p><div id="reading-feedback"></div></section></div>`;
  $('#reading-save').onclick=()=>save(c);$('#reading-plan-task').onclick=()=>window.dispatchEvent(new CustomEvent('awl-planner-request',{detail:{title:'Work on my summary of '+note.title,route:href(id),source_path:note.vault_path}}));$('#reading-history').onclick=()=>history(c);
  document.querySelectorAll('[data-reading-field]').forEach(el=>{el.oninput=()=>{c.fields[el.dataset.readingField]=el.value;changed(c)}});
  $('#reading-add-quote').onclick=()=>addQuote(c);
  if($('#reading-add-chapter'))$('#reading-add-chapter').onclick=async()=>{if(await save(c))createForm({book:c.note})};
  $('#reading-focus').onclick=()=>window.dispatchEvent(new CustomEvent('awl-focus-request',{detail:{goal:'Summary · '+note.title,route:href(id),source_path:note.vault_path}}));
  window.dispatchEvent(new CustomEvent('awl-focus-context',{detail:{goal:'Summary · '+note.title,route:href(id),source_path:note.vault_path}}));
  window.dispatchEvent(new CustomEvent('awl-reading-open',{detail:{id,title:note.title}}));
  $('#reading-ask').onclick=async()=>{const button=$('#reading-ask');button.disabled=true;try{
   if(!await save(c))throw new Error('Compare or recover your draft before requesting feedback.');if(!active(c))return;
   const job=await api(base(id)+'/reviews',{base_hash:c.note.hash,question:$('#reading-question').value,focus:$('#reading-review-focus').value});c.reviews=[job,...c.reviews];if(!active(c))return;drawReviews(c);$('#reading-tutor-status').textContent='The tutor is reading your saved summary. You can keep writing or return through Continue your work.';startPoll(c);
  }catch(e){if(active(c))$('#reading-tutor-status').textContent=e.message}finally{button.disabled=false}};
  updateCount(c);drawReviews(c);showRecovery(c);if(note.conflict){c.error='This reading note has competing saved versions. Compare them before saving.';showRecovery(c)}startPoll(c);
 }
 function addQuote(c){
  modal('Keep a quotation with its context',`<form id="reading-quote-form"><label class="field">Exact words from the source<textarea name="text" rows="5" maxlength="16000" required></textarea></label><label class="field">Printed page, chapter or stable location<input name="page" maxlength="150" required placeholder="e.g. p. 42, chapter 3"></label><label class="field">What is the author discussing here?<textarea name="context" rows="3" maxlength="2000" required></textarea></label><label class="field">My interpretation and limits<textarea name="interpretation" rows="3" maxlength="2000"></textarea></label><label class="reading-check"><input name="checked" type="checkbox"> I checked these exact words against the source.</label><button class="btn" type="submit">Add to my quotation notebook</button><p id="reading-quote-status" role="status"></p></form>`);
  $('#reading-quote-form').onsubmit=event=>{event.preventDefault();try{const f=new FormData(event.currentTarget),quote=quotationMarkdown({text:f.get('text'),page:f.get('page'),context:f.get('context'),interpretation:f.get('interpretation'),checked:f.get('checked')==='on'});const combined=(c.fields['Quotations with context']||'').trim()+'\n\n'+quote;if(combined.length>60000)throw new Error('This notebook is full. Use a separate chapter document.');c.fields['Quotations with context']=combined.trim();$('#modal').close();setFields(c);changed(c)}catch(e){$('#reading-quote-status').textContent=e.message}};
 }
 function drawReviews(c){
  if(!active(c)||!$('#reading-feedback'))return;
  $('#reading-feedback').innerHTML=c.reviews.map((job,index)=>`<details class="reading-review" ${index===0?'open':''}><summary>${esc(new Date(job.created).toLocaleString())} · ${esc({queued:'Waiting for local tutor',running:'Reading your summary',done:'Feedback ready',failed:'Review needs attention',interrupted:'Review interrupted'}[job.status]||job.status)}</summary><p class="reading-review-scope">${esc(job.scope)} ${readingFeedbackIsCurrent(job,c.fields['My summary'])?'Your summary matches this review.':'You have changed the summary since this review was requested.'}</p><details><summary>Summary sent for this review</summary><pre>${esc(job.reviewed_text)}</pre></details>${job.result?`<h3>My reading of your meaning</h3><p>${esc(job.result.meaning)}</p><h3>What works</h3>${job.result.strengths.length?job.result.strengths.map(s=>`<blockquote>${esc(s.quote)}</blockquote><p>${esc(s.explanation)}</p>`).join(''):'<p>No specific strengths were identified in this response.</p>'}<h3>One revision at a time</h3>${job.result.priorities.map(p=>`<article>${p.quote?`<blockquote>${esc(p.quote)}</blockquote>`:''}<p>${esc(p.explanation)}</p><p><strong>Try this:</strong> ${esc(p.tip)}</p></article>`).join('')}<h3>Questions about the source</h3><ul>${job.result.source_questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><p class="reading-next"><strong>Next step:</strong> ${esc(job.result.next_step)}</p><button class="btn secondary" data-reading-plan-next="${esc(job.id)}">Plan this next step</button><p class="tiny">${esc(job.model)} · Suggestions for your judgement. No proficiency score or claim that the full source has been verified.</p>`:''}${job.error?`<p class="alert error">${esc(job.error)}</p>`:''}</details>`).join('');
  document.querySelectorAll('[data-reading-plan-next]').forEach(button=>button.onclick=()=>window.dispatchEvent(new CustomEvent('awl-planner-request',{detail:{title:c.reviews.find(j=>j.id===button.dataset.readingPlanNext).result.next_step,route:href(c.note.id),source_path:c.note.vault_path}})));
 }
 function startPoll(c){clearTimeout(pollTimer);if(!active(c)||!c.reviews.some(j=>['queued','running'].includes(j.status)))return;pollTimer=setTimeout(async()=>{try{const jobs=await api(base(c.note.id)+'/reviews');if(!active(c))return;c.reviews=jobs;drawReviews(c);if(!jobs.some(j=>['queued','running'].includes(j.status)))$('#reading-tutor-status').textContent='Review finished. Your editor remains available.'}catch(e){message(c,'Could not refresh tutor status. Reopen this note to check again.',true)}startPoll(c)},3000)}
 window.addEventListener('beforeunload',e=>{if(ctx?.dirty){keep(ctx);e.preventDefault();e.returnValue=''}});
 return {render,leave:async()=>{clearTimeout(saveTimer);clearTimeout(pollTimer);const old=ctx;await save(old);if(ctx===old)ctx=null}};
}
